const pages = {"/":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Alltabs — Your synced tabs, within reach</title>\n<meta name=\"description\" content=\"Find tabs from your other Chrome devices in one side panel. Search, open, and copy links. Local processing, no upload to Alltabs.\">\n<link rel=\"icon\" type=\"image/png\" href=\"/assets/icon.png\">\n<style>\n:root{color-scheme:light;--ink:#18181b;--muted:#62626c;--line:#e4e4e7;--paper:#ffffff;--accent:#2563eb}\n*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.7 system-ui,sans-serif}a{color:var(--accent);text-underline-offset:4px}a:hover{text-decoration:underline}a:focus-visible{outline:3px solid var(--accent);outline-offset:5px}header,main,footer{width:min(1120px,calc(100% - 64px));margin:auto}header{display:flex;align-items:center;justify-content:space-between;padding:22px 0;border-bottom:1px solid var(--line);gap:24px}.brand{display:flex;align-items:center;gap:10px;font-size:22px;font-weight:750;text-decoration:none;color:var(--ink)}.brand img{width:38px;height:38px}nav{display:flex;align-items:center;gap:26px;font-size:14px;font-weight:550}nav a{text-decoration:none}.nav-source{border:1px solid var(--line);border-radius:8px;padding:7px 14px;background:#fff}.hero{display:grid;grid-template-columns:minmax(0,1fr) 370px;align-items:center;gap:88px;padding:72px 0 80px}.eyebrow{font-size:12px;letter-spacing:.11em;text-transform:uppercase;font-weight:650;color:var(--muted)}h1{font-size:clamp(44px,5.7vw,72px);line-height:1.06;letter-spacing:-.055em;margin:22px 0 26px;font-weight:750}h1 span{color:#2563eb}.intro{font-size:20px;line-height:1.65;max-width:490px;color:var(--muted);margin:0 0 26px}.hero-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;gap:12px;background:var(--ink);color:#fff;padding:11px 20px;border:1px solid var(--ink);border-radius:8px;text-decoration:none;font-size:15px;font-weight:600}.button:hover{background:#27272a;text-decoration:none}.store-status{display:inline-block;color:var(--muted);font-size:13px;line-height:1.5;padding:10px 0}.release{font-size:13px;color:var(--muted);max-width:435px;margin:14px 0 22px}.local{font-size:13px;color:var(--muted);font-weight:550}.local span{color:var(--accent);margin-right:5px}figure{margin:0;padding:20px 22px 14px;border:1px solid var(--line);border-radius:20px;background:#fafafa;box-shadow:0 18px 50px -28px #18181b50}figure img{display:block;width:100%;height:auto;border:1px solid #e4e4e7;border-radius:9px;box-shadow:0 8px 24px -14px #18181b50}figcaption{font-size:11px;letter-spacing:.02em;color:var(--muted);text-align:center;padding-top:12px}h2{font-size:28px;line-height:1.25;letter-spacing:-.03em;margin:0}h3{font-size:17px;margin:0 0 8px}.features{border-top:1px solid var(--line);padding:56px 0 64px}.features>.eyebrow{margin:0 0 14px}.features>h2{font-size:clamp(28px,4vw,38px);max-width:680px}.feature-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px 36px;margin-top:38px;counter-reset:feature}.feature-grid>div{border-top:1px solid var(--line);padding-top:18px}.feature-grid>div:before{counter-increment:feature;content:\"0\" counter(feature);display:block;font-size:11px;font-weight:650;letter-spacing:.08em;color:#2563eb;margin-bottom:10px}.feature-grid h3{font-size:18px;line-height:1.4;margin-bottom:9px}.feature-grid p{font-size:15px;color:var(--muted);margin:0}.details{padding:38px;display:grid;grid-template-columns:240px minmax(0,1fr);gap:44px;background:#fafafa;border:1px solid var(--line);border-radius:14px}.details p{margin:0 0 16px}.note{font-size:14px;color:var(--muted)}.details a{font-size:14px;font-weight:600}.requirements{padding:30px 0;font-size:13px;color:var(--muted)}.requirements h2{font-size:13px;letter-spacing:0;margin-bottom:8px}.requirements p{margin:6px 0;max-width:950px}footer{border-top:1px solid var(--line);padding:24px 0 32px;font-size:12px;color:var(--muted)}footer p{margin:8px 0}footer a{overflow-wrap:anywhere}.footer-top{display:flex;justify-content:space-between;align-items:center;gap:16px}.footer-links{display:flex;gap:22px}.footer-top strong{color:var(--ink);font-size:15px}.hosting{max-width:780px}\n@media(max-width:900px){.hero{gap:36px;grid-template-columns:minmax(0,1fr) 310px;padding:52px 0 60px}.feature-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.details{grid-template-columns:1fr;gap:24px}h1{font-size:56px}nav{gap:18px}}\n@media(max-width:650px){header,main,footer{width:calc(100% - 36px)}header{padding:16px 0;gap:16px;flex-wrap:wrap}nav{gap:18px;font-size:13px}.nav-source{padding:5px 10px}.hero{grid-template-columns:1fr;padding:40px 0;gap:32px}h1{font-size:clamp(42px,10vw,60px)}.intro{font-size:18px}figure{width:min(350px,100%);margin:auto}.features{padding:36px 0}.feature-grid{grid-template-columns:1fr;gap:24px;margin-top:28px}.details{padding:24px}.footer-top{align-items:flex-start;flex-direction:column;gap:0}.footer-links{gap:18px}}\n.chrome-button{font-family:inherit;cursor:pointer;opacity:1}.secondary{background:#f4f4f5;border-color:#e4e4e7;color:#18181b;box-shadow:0 1px 2px #0000000d}.secondary:hover{background:#e4e4e7}.chrome-button:hover{background:#18181b}.hero{position:relative}.hero:before{content:\"\";position:absolute;inset:0 -24px;z-index:-1;background-image:radial-gradient(#e4e4e7 1px,transparent 1px);background-size:22px 22px;mask-image:linear-gradient(transparent,#00000038 30%,transparent 95%)}.button{min-height:46px;border-radius:10px}.feature-grid>div:before{color:#71717b}.local span{color:#52525b}\n/* Soft blue and lavender surfaces; outlined pill actions. */\nbody{background:linear-gradient(135deg,#f3f6ff 0%,#faf9ff 45%,#f7faff 100%);background-attachment:fixed}.hero{isolation:isolate}.hero:before{inset:22px -28px;background:radial-gradient(ellipse at 82% 32%,#dce5ffb3,transparent 60%),radial-gradient(ellipse at 12% 80%,#ece5ffc2,transparent 55%);mask-image:none;border-radius:32px}figure{background:linear-gradient(145deg,#e6edff,#f2edff);border-color:#d5dcf0;box-shadow:0 22px 60px -32px #465aa070}.features{border-top-color:#d7deed}.feature-grid>div{border-top-color:#d7deed}.feature-grid>div:before{color:#6573a4}.details{background:linear-gradient(125deg,#edf2ff,#f6f2fc);border-color:#d7deed}.nav-source{background:#ffffffb8;border-color:#d7deed}.button,.button:hover,.chrome-button:hover,.secondary,.secondary:hover{padding:2px;min-height:0;border:0;border-radius:999px;background:linear-gradient(105deg,#27272a,#3b82f6);box-shadow:none;color:#18181b;overflow:hidden;text-decoration:none}.button-inner{display:flex;align-items:center;justify-content:center;gap:10px;border-radius:999px;background:#fbfcff;padding:12px 22px;font-size:16px;font-weight:550;line-height:24px;transition:background-color 180ms,color 180ms}.button:not(:disabled):hover .button-inner{background:transparent;color:#fff}.button:not(:disabled):active .button-inner{background:#1e3a8a;color:#fff}.button-arrow{transition:transform 180ms}.button:hover .button-arrow{transform:translateX(3px)}.chrome-button{cursor:pointer}.secondary{background:linear-gradient(105deg,#64748b,#818cf8)}.release{max-width:460px}.hero-actions{gap:14px}.button:focus-visible{outline:3px solid #2563eb;outline-offset:4px}footer{border-top-color:#d7deed}@media(max-width:650px){.hero:before{inset:16px -12px}.button-inner{padding:12px 20px}}@media(prefers-reduced-motion:reduce){.button-inner,.button-arrow{transition:none}.button:hover .button-arrow{transform:none}}\n</style></head><body>\n<header><a class=\"brand\" href=\"/\" aria-label=\"Alltabs home\"><img src=\"/assets/icon.png\" width=\"44\" height=\"44\" alt=\"\">Alltabs</a><nav aria-label=\"Main navigation\"><a href=\"#features\">Features</a><a href=\"#privacy\">Privacy</a><a class=\"nav-source\" href=\"https://github.com/oahz48/alltabs\">GitHub ↗</a></nav></header>\n<main><section class=\"hero\" aria-labelledby=\"headline\">\n<div><p class=\"eyebrow\">For Chrome on desktop</p><h1 id=\"headline\">Your other tabs,<br><span>within reach.</span></h1><p class=\"intro\">That page you left on your laptop? Find it here. Browse tabs from your other Chrome devices in one persistent side panel.</p><div class=\"hero-actions\"><a class=\"button chrome-button\" href=\"https://chromewebstore.google.com/detail/alltabs/ikneolohkckpkfmkbplmcneeaaelneoa\" aria-describedby=\"release\"><span class=\"button-inner\"><svg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"12\" cy=\"12\" r=\"9\" stroke=\"currentColor\" stroke-width=\"1.6\"/><circle cx=\"12\" cy=\"12\" r=\"3.5\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M12 8.5h8M15 13.8l-4 7M9 13.8 5 6.5\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg> Add to Chrome</span></a><a class=\"button secondary\" href=\"https://github.com/oahz48/alltabs\"><span class=\"button-inner\">View on GitHub <span class=\"button-arrow\" aria-hidden=\"true\">→</span></span></a></div><p class=\"release\" id=\"release\">Available now on the Chrome Web Store.</p><p class=\"local\"><span aria-hidden=\"true\">✓</span> Free &amp; open source · Local processing</p></div>\n<figure><a href=\"/assets/panel-preview.png\" aria-label=\"Open full-size Alltabs panel preview\"><img src=\"/assets/panel-preview.png\" width=\"380\" height=\"820\" alt=\"Alltabs side panel showing search and tabs grouped by synced device, with selection checkboxes.\"></a><figcaption>Actual panel interface · sample data</figcaption></figure>\n</section>\n<section class=\"features\" aria-labelledby=\"features\"><p class=\"eyebrow\">A little less searching. A little more doing.</p><h2 id=\"features\">What you can do with Alltabs</h2><div class=\"feature-grid\">\n<div><h3>Browse your other devices</h3><p>Find the tabs you left on your laptop, desktop, or phone, grouped by device in one side panel.</p></div>\n<div><h3>Find a page fast</h3><p>Search page titles and addresses across visible devices. Jump straight to the tab you have in mind.</p></div>\n<div><h3>Open one tab or a whole batch</h3><p>Open a single page, select a few, or open all tabs from a device on the computer you’re using now.</p></div>\n<div><h3>Copy the links you need</h3><p>Select tabs and copy their links, one per line, ready to paste into notes, a message, or a project document.</p></div>\n<div><h3>Choose which devices you see</h3><p>Hide devices you don’t need and restore them in settings. Keep your panel focused on what matters.</p></div>\n<div><h3>Keep your place as you browse</h3><p>The side panel stays open as you open tabs, preserving your search and position. Device expansion choices are remembered.</p></div>\n</div></section>\n<section class=\"details\" aria-labelledby=\"privacy\"><h2 id=\"privacy\">Your tabs stay<br>your business.</h2><div><h3>Local processing. No upload to Alltabs.</h3><p>Alltabs processes tab titles, URLs, searches, and selections locally on your device. It does not upload this data to the developer, the Alltabs website, or any developer-operated server. There is no Alltabs account, analytics, tracking, advertising, or remote code.</p><p class=\"note\">Tabs from other devices are supplied by Chrome's own sync service. Alltabs reads the snapshots Chrome makes available; it does not operate a separate sync service. Website icons use Chrome's built-in favicon service, and opening a link connects your browser to that website. These Chrome services and destination websites have their own privacy behavior.</p><a href=\"/privacy\">Read the privacy policy →</a></div></section>\n<aside class=\"requirements\" aria-labelledby=\"requirements\"><h2 id=\"requirements\">System requirements</h2><p>Desktop Chrome 141 or newer on Windows or macOS. Sign into the same Chrome profile on your devices with history and open-tab sync enabled. Phones supply tabs through Chrome sync and do not need Alltabs installed.</p><p>Tab availability and freshness depend on Chrome sync. Alltabs cannot force another device to sync or close remote tabs.</p></aside>\n</main><footer id=\"support\"><div class=\"footer-top\"><p><strong>Alltabs</strong> · Published by z0</p><div class=\"footer-links\"><a href=\"https://github.com/oahz48/alltabs\">GitHub ↗</a><a href=\"https://github.com/oahz48/alltabs/blob/main/LICENSE\">MIT License</a><a href=\"/privacy\">Privacy</a></div></div><p>Help or privacy questions? <a href=\"mailto:oahz48@gmail.com\">oahz48@gmail.com</a></p><p class=\"hosting\">This website is hosted by Cloudflare. It receives ordinary web requests to deliver these pages. The extension does not send your tab list to this website.</p></footer>\n</body></html>\n","/privacy":"<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Alltabs Privacy Policy</title><style>body{max-width:850px;margin:50px auto;padding:0 24px;color:#18181b;background:#ffffff;font:17px/1.65 system-ui,sans-serif}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%;font-size:15px}td,th{text-align:left;border-bottom:1px solid #e4e4e7;padding:10px;vertical-align:top}code{font-size:.9em}li{margin:8px 0}</style><main><h1>Alltabs privacy</h1>\n<p>Alltabs displays open tabs that Chrome makes available from your synced devices, plus non-incognito tabs from the current computer. Tab titles and addresses are used only to display, search, select, copy, and open tabs at your request.</p>\n<h2>Local processing; no upload to Alltabs</h2>\n<p>Alltabs processes tab titles, URLs, searches, and selections locally on your device. It does not upload this data to the developer, the Alltabs website, or any developer-operated server. There is no Alltabs account, analytics, tracking, advertising, or remote code.</p>\n<p>Tabs from other devices are supplied by Chrome's own sync service. Alltabs reads the snapshots Chrome makes available; it does not operate a separate sync service. Website icons use Chrome's built-in favicon service, and opening a link connects your browser to that website. These Chrome services and destination websites have their own privacy behavior.</p>\n<h2>Local storage</h2>\n<ul><li>Chrome extension local storage holds expanded-device choices, hidden device names, and the preference to show the current device. These preferences are not synced by Alltabs.</li><li>Chrome extension session storage holds per-window search text, scroll position, and selected tab identifiers. Chrome clears this storage when the browser session ends or the extension is disabled, reloaded, updated, or removed.</li><li>Tab snapshots stay in panel memory. Alltabs does not maintain a separate saved browsing history.</li><li>Copy links writes only the selected URLs to the clipboard when you press that button.</li></ul>\n<p>Removing Alltabs removes its extension storage. Chrome sync and the operating system clipboard are managed separately by Chrome and your operating system.</p>\n<h2>Permissions</h2>\n<table><tr><th>Permission</th><th>Purpose</th></tr><tr><td><code>sidePanel</code></td><td>Display the panel and support opening, toggling, and closing it.</td></tr><tr><td><code>sessions</code></td><td>Read the synced device and window snapshots Chrome exposes.</td></tr><tr><td><code>tabs</code></td><td>Read titles and URLs of current-device tabs and synced tab details.</td></tr><tr><td><code>storage</code></td><td>Remember display preferences and panel state on this computer.</td></tr><tr><td><code>favicon</code></td><td>Display website icons through Chrome's built-in favicon service.</td></tr><tr><td><code>clipboardWrite</code></td><td>Copy selected links when you request it.</td></tr></table>\n<p>Alltabs requests no website host permissions and injects no code into web pages. Opening a link navigates Chrome to that destination; those websites and Chrome's own sync and favicon services have their own privacy behavior.</p>\n<p>Alltabs uses browsing data only to provide its visible tab-management features. It does not sell this data, use it for advertising, or use it for credit or lending decisions. Its use of information complies with the Chrome Web Store User Data Policy, including the Limited Use requirements.</p>\n<p>Last updated: September 7, 2026. Applies to Alltabs 0.1.0.</p>\n<h2>Contact</h2>\n<p>Publisher: z0. For support or privacy questions, contact oahz48@gmail.com.</p></main></html>\n"};
const assets = {"/assets/icon.png":"","/assets/panel-preview.png":""};
addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  const path = url.pathname === '/privacy/' || url.pathname === '/privacy.html' ? '/privacy' : url.pathname;
  const isAsset = Object.hasOwn(assets, path);
  const body = isAsset ? Uint8Array.from(atob(assets[path]), c => c.charCodeAt(0)) : Object.hasOwn(pages, path) ? pages[path] : undefined;
  const allowed = request.method === 'GET' || request.method === 'HEAD';
  event.respondWith(new Response(request.method === 'HEAD' ? null : (allowed ? (body || 'Not found') : 'Method not allowed'), {status: !allowed ? 405 : body ? 200 : 404, headers: {
    'Content-Type': !allowed ? 'text/plain; charset=utf-8' : isAsset ? 'image/png' : body ? 'text/html; charset=utf-8' : 'text/plain; charset=utf-8',
    'Content-Security-Policy': "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'",
    'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer', 'Cache-Control': 'public, max-age=300',
    ...(!allowed ? {Allow: 'GET, HEAD'} : {})
  }}));
});
